import '../../../storage/memory_store.dart';
import '../memory.dart';
import '../memory_repository.dart';
class InMemoryMemoryRepository implements MemoryRepository { final MemoryStore _store; InMemoryMemoryRepository(this._store); @override Future<Memory> save(Memory m) => _store.save(m); @override Future<Memory?> getById(String id) => _store.getById(id); @override Future<List<Memory>> getAll() => _store.getAll(); @override Future<List<Memory>> search(String query) => _store.search(query); @override Future<List<Memory>> getByConversation(String conversationId) => _store.getByConversation(conversationId); @override Future<List<Memory>> searchInConversation(String conversationId, String query) async { final list = await _store.getByConversation(conversationId); if (query.isEmpty) return list; final lower = query.toLowerCase(); return list.where((m) => m.content.toLowerCase().contains(lower)).toList(); } @override Future<void> delete(String id) => _store.delete(id); @override Future<void> deleteConversation(String conversationId) => _store.deleteConversation(conversationId); @override Future<void> clear() => _store.clear(); @override Future<int> count() => _store.count(); }
